args.command:
python3 - <<'PY'
import requests, json
south,west,north,east=12.725,78.173,12.7415,78.1955
query=f'''
[out:json][timeout:25];
(
  way["natural"="water"]({south},{west},{north},{east});
  relation["natural"="water"]({south},{west},{north},{east});
  way["waterway"]({south},{west},{north},{east});
  relation["waterway"]({south},{west},{north},{east});
  way["landuse"="reservoir"]({south},{west},{north},{east});
  way["landuse"="pond"]({south},{west},{north},{east});
);
out tags center geom 20;
'''
r=requests.get('https://overpass-api.de/api/interpreter',params={'data':query},timeout=60)
print('status',r.status_code)
js=r.json()
print('elements',len(js.get('elements',[])))
for el in js.get('elements',[])[:20]:
    print(el['type'], el['id'], el.get('tags',{}), el.get('center'))
PY

